OWNER_COST_GATE_POLICY_VALUES = frozenset({"owner_gated", "disabled_by_owner"})


def _resolved_cost_policy() -> tuple[dict[str, str], str]:
    raw_manifest = os.getenv(RESOLVED_COST_POLICY_JSON_ENV)
    raw_sha256 = os.getenv(RESOLVED_COST_POLICY_SHA256_ENV)
    legacy_value = os.getenv(OWNER_COST_GATE_POLICY_ENV)
    if raw_manifest is not None or raw_sha256 is not None:
        if raw_manifest is None or raw_sha256 is None or legacy_value is not None:
            raise RuntimeError("resolved cost policy manifest transport is incomplete")
        try:
            manifest = json.loads(raw_manifest)
        except (json.JSONDecodeError, UnicodeError) as exc:
            raise RuntimeError("resolved cost policy manifest is invalid JSON") from exc
        if (
            not isinstance(manifest, dict)
            or set(manifest) != {"schema_version", "policy", "authority"}
            or manifest.get("schema_version") != RESOLVED_COST_POLICY_SCHEMA
            or manifest.get("policy") not in OWNER_COST_GATE_POLICY_VALUES
            or manifest.get("authority") != "owner_wrapper"
        ):
            raise RuntimeError("resolved cost policy manifest has an invalid shape")
        canonical = json.dumps(
            manifest,
            allow_nan=False,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )
        digest = hashlib.sha256(canonical.encode("utf-8")).hexdigest()
        if raw_manifest != canonical or raw_sha256 != digest:
            raise RuntimeError("resolved cost policy manifest digest mismatch")
        return {key: str(value) for key, value in manifest.items()}, digest
    policy = (legacy_value or "owner_gated").strip()
    if policy not in OWNER_COST_GATE_POLICY_VALUES:
        raise RuntimeError(
            f"{OWNER_COST_GATE_POLICY_ENV} must be one of "
            + ", ".join(sorted(OWNER_COST_GATE_POLICY_VALUES))
        )
    manifest = {
        "schema_version": RESOLVED_COST_POLICY_SCHEMA,
        "policy": policy,
        "authority": "owner_wrapper",
    }
    canonical = json.dumps(
        manifest,
        allow_nan=False,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )
    return manifest, hashlib.sha256(canonical.encode("utf-8")).hexdigest()


OWNER_COST_GATE_POLICY_MANIFEST, OWNER_COST_GATE_POLICY_MANIFEST_SHA256 = (
    _resolved_cost_policy()
)
