def _legacy_post_review_phase(review_ordinal: int) -> str:
    if review_ordinal == 1:
        return "work_30_60"
    if review_ordinal == 2:
        return "work_60_90"
    raise ValueError("review ordinal must be one or two")


def _post_review_phase(review_ordinal: int) -> str:
    if review_ordinal == 1:
        return "work_60_120"
    if review_ordinal == 2:
        return "work_120_150"
    raise ValueError("review ordinal must be one or two")


def _released_guardian_enforcement(*, test_bypass: bool = False) -> bool:
    """Return whether production-only Guardian contracts must be enforced.

    ``test_bypass`` and ``_TEST_ALLOW_UNRELEASED_PAID_WORK`` are unreachable
    from the CLI. They keep low-level ledger tests independent of a fully
    materialized launcher manifest while production always takes this branch.
    """

    return bool(
        REVIEW_CADENCE_POLICY["guardian_enforcement_ready"] is True
        and not _TEST_ALLOW_UNRELEASED_PAID_WORK
        and not test_bypass
    )


